import {readFileSync} from 'node:fs';
const [workloadPath, driverPath] = process.argv.slice(2);
const readText = path => readFileSync(path, 'utf8');
const now = () => Number(process.hrtime.bigint());
const output = console.log;

(0, eval)(readText(workloadPath));
(0, eval)(readText(driverPath));
const first = benchmarkBatch(1);
if (first && typeof first.then === 'function') await first;
benchmarkChecksum();
const warmup_batch_ns = [];
const timed_batch_ns = [];
let checksum;
for (let index = 0; index < 80; index++) {
    const start = now();
    const result = benchmarkBatch(10);
    if (result && typeof result.then === 'function') await result;
    const elapsed = Math.round(now() - start);
    const current = benchmarkChecksum();
    if (index < 64) {
        warmup_batch_ns.push(elapsed);
    } else {
        if (index === 64) checksum = current;
        else if (checksum !== current) throw new Error('checksum changed at batch ' + index);
        timed_batch_ns.push(elapsed);
    }
}
output(JSON.stringify({checksum, warmup_batch_ns, timed_batch_ns}));

