use rquickjs::{Context, Function, Runtime};
use rquickjs_jit::{Jit, JitConfig};
use std::{env, fs, time::Instant};

fn main() {
    let path = env::args().nth(1).expect("bundle path");
    let source = fs::read_to_string(path).expect("read bundle").replacen(
        "\nsuite.run();",
        r#"
globalThis.__webToolingCount = suite.length;
globalThis.__runWebTooling = function(index) {
    const benchmark = suite[index];
    benchmark.run();
    if (benchmark.error) throw benchmark.error;
    console.log(benchmark.name + ': ' + benchmark.hz.toFixed(2) + ' runs/s');
};
"#,
        1,
    );
    let runtime = Runtime::new().expect("runtime");
    let context = Context::full(&runtime).expect("context");
    let count = context.with(|ctx| {
        let start = Instant::now();
        ctx.globals().set("print", Function::new(ctx.clone(), |line: String| println!("{line}")).unwrap()).unwrap();
        ctx.globals().set("__benchmarkClock", Function::new(ctx.clone(), move || start.elapsed().as_secs_f64() * 1000.0).unwrap()).unwrap();
        ctx.eval::<(), _>("globalThis.global = globalThis; globalThis.console = {log: print}; globalThis.performance = { now: __benchmarkClock };").unwrap();
        if let Err(error) = ctx.eval::<(), _>(source.as_bytes()) {
            eprintln!("Web Tooling setup error: {error}: {:?}", ctx.catch());
            std::process::exit(1);
        }
        ctx.globals().get::<_, u32>("__webToolingCount").unwrap()
    });
    let jit = Jit::attach(&runtime, JitConfig::builder().build().unwrap()).expect("JIT");
    let mut errors = 0;
    for index in 0..count {
        errors += context.with(|ctx| {
            let run: Function = ctx.globals().get("__runWebTooling").unwrap();
            if let Err(error) = run.call::<_, ()>((index,)) {
                eprintln!("Web Tooling case {index} failed: {error}: {:?}", ctx.catch());
                1
            } else {
                0
            }
        });
        jit.poll();
    }
    let metrics = jit.metrics();
    eprintln!("Longbridge: native_entries={} tier2_entries={} installed={} deopts={}", metrics.native_entries, metrics.tier2_entries, metrics.installed, metrics.deopts);
    if errors > 0 { std::process::exit(1); }
}
